"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["35723"],{97609(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_taxa_inscricao.valor_nao_permitido_quando_nao_cobra","status":422,"titulo":"Processo que declara n\xe3o cobrar taxa n\xe3o pode informar valor"},"descricao":{"codigo":"uniplus.selecao.configuracao_taxa_inscricao.valor_nao_permitido_quando_nao_cobra","requisitos":[],"oQueAconteceu":["A defini\xe7\xe3o declarou `cobra` como falso, isto \xe9, que o processo n\xe3o cobra taxa de inscri\xe7\xe3o, mas\\ntrouxe `valor`. Qualquer valor informado nesse caso \xe9 recusado, inclusive zero: o processo que n\xe3o\\ncobra n\xe3o declara valor.","A recusa acontece depois de o sistema encontrar o processo e aceitar a precondi\xe7\xe3o de edi\xe7\xe3o. As\\nviola\xe7\xf5es do mesmo pedido saem juntas no array `errors[]`: esta causa pode aparecer ao lado de\\n[`fundamento_exige_cobranca`](/erros/uniplus.selecao.configuracao_taxa_inscricao.fundamento_exige_cobranca)\\ne de\\n[`fundamento_desconhecido`](/erros/uniplus.selecao.configuracao_taxa_inscricao.fundamento_desconhecido),\\nquando o pedido tamb\xe9m traz fundamentos de isen\xe7\xe3o.","Esta mesma confer\xeancia \xe9 refeita quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada: em toda opera\xe7\xe3o que l\xea essa configura\xe7\xe3o e devolve a viola\xe7\xe3o ao chamador (a retifica\xe7\xe3o, a consulta dos formul\xe1rios,\\nas opera\xe7\xf5es da inscri\xe7\xe3o, entre outras; a lista completa est\xe1 no cabe\xe7alho da p\xe1gina).\\nPelo caminho normal de grava\xe7\xe3o, a configura\xe7\xe3o congelada nunca traz valor em processo que n\xe3o\\ncobra, porque a defini\xe7\xe3o o recusa antes. Nessas leituras a recusa sai como viola\xe7\xe3o \xfanica, sem a\\nlista `errors[]`, e se refere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Escolha entre:","- retirar `valor` do pedido, se o processo n\xe3o cobra taxa; ou\\n- declarar `cobra` como verdadeiro, com valor positivo e ao menos um fundamento de isen\xe7\xe3o, se o\\n  processo cobra.","Se a resposta trouxer mais de uma viola\xe7\xe3o em `errors[]`, corrija todas antes de reenviar.","Se a recusa apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer uma das listadas no cabe\xe7alho, exceto a defini\xe7\xe3o da pr\xf3pria configura\xe7\xe3o e a simula\xe7\xe3o), o pedido enviado agora n\xe3o \xe9 a causa: o sistema\\nrecusou a configura\xe7\xe3o congelada da vers\xe3o publicada, e redefinir a taxa do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o da taxa de inscri\xe7\xe3o do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Apresenta\xe7\xe3o do formul\xe1rio do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, envio, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao taxa inscricao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);